import { EChartsType } from '@/src/echarts';
import { createChart } from '@/test/ut/core/utHelper';
import SunburstPiece from '@/src/chart/sunburst/SunburstPiece';

describe('sunburst_root_label_centering', function () {

    let chart: EChartsType;
    beforeEach(function () {
        chart = createChart({ width: 500, height: 400 });
    });

    afterEach(function () {
        chart.dispose();
    });

    function getRootPiece(chart: EChartsType): SunburstPiece {
        let rootPiece: SunburstPiece = null;
        (chart as any).getZr().storage.traverse(function (el: any) {
            if (el instanceof SunburstPiece && el.node && el.node.depth === 0) {
                rootPiece = el;
            }
        });
        return rootPiece;
    }

    it('root label should be centered for a full-circle root', function () {
        chart.setOption({
            series: {
                type: 'sunburst',
                // Values whose sum makes `endAngle - startAngle`
                // slightly different from 2 * Math.PI due to
                // floating point computation.
                data: [{ value: 0.1 }, { value: 0.2 }],
                label: { show: true }
            }
        });

        const rootPiece = getRootPiece(chart);
        expect(rootPiece).toBeTruthy();

        const layout = rootPiece.node.getLayout();
        // Sanity check: the root is a full circle but the computed
        // angle is not exactly 2 * Math.PI.
        expect(layout.r0).toBe(0);
        expect(layout.endAngle - layout.startAngle).not.toBe(2 * Math.PI);

        const label = rootPiece.getTextContent();
        expect(label).toBeTruthy();
        expect(label.x).toBe(layout.cx);
        expect(label.y).toBe(layout.cy);
    });

    it('root label should be centered after rootToNode drill down', function () {
        chart.setOption({
            series: {
                type: 'sunburst',
                data: [{
                    name: 'A',
                    value: 0.1,
                    children: [{ value: 0.04 }, { value: 0.06 }]
                }, {
                    name: 'B',
                    value: 0.2
                }],
                label: { show: true }
            }
        });

        chart.dispatchAction({
            type: 'sunburstRootToNode',
            targetNodeId: '0'
        });

        const rootPiece = getRootPiece(chart);
        expect(rootPiece).toBeTruthy();

        const layout = rootPiece.node.getLayout();
        const label = rootPiece.getTextContent();
        expect(label).toBeTruthy();
        expect(label.x).toBe(layout.cx);
        expect(label.y).toBe(layout.cy);
    });
});

